fn removeElement(nums: &mut Vec<i32>, val: i32) -> usize {
    // i will mark the position where we write the next non-val element
    let mut i = 0;
    // Traverse each element in the array
    for j in 0..nums.len() {
        // If the current element is not the target, write it at index i
        if nums[j] != val {
            nums[i] = nums[j];
            i += 1;
        }
    }
    // i is now the length of the "filtered" prefix
    i
}

